use super::*;
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::*};
fn fixture()->Grid3dSnapshot{let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let bits=|s:&str|f64::from_bits(u64::from_str_radix(s,16).unwrap());Grid3dSnapshot{schema:f["schema"].as_str().unwrap().into(),seed:u64::MAX,width:u32::MAX,height:2,depth:3,cell_sizes_x:f["cellSizesXBits"].as_array().unwrap().iter().map(|v|bits(v.as_str().unwrap())).collect(),cell_sizes_y:vec![f64::from_bits(1)],cell_sizes_z:vec![f64::INFINITY,f64::NEG_INFINITY],periodic_x:true,periodic_y:false,periodic_z:true,tiles:vec![Grid3dTile{id:"mesh 🧬".into(),label:Some("".into()),weight:1.,media:Grid3dTileMedia::Mesh{mesh:Grid3dMesh{positions:vec![-0.,f64::from_bits(0x7ff8000000004321),f64::from_bits(1),1.],indices:vec![u32::MAX,0],color:Some(Grid3dColor{r:u32::MAX,g:2,b:3,a:4})}}},Grid3dTile{id:"child".into(),label:None,weight:f64::from_bits(0x7ff0000000000001),media:Grid3dTileMedia::MeshChild{child:store::ArtifactChild::new("owned-child".into(),store::os_io::ArtifactRef{artifact_id:"semio-mesh".into(),dialect:store::os_io::ArtifactDialect{artifact_kind:"s.stdio.semio".into(),standard:"v1".into(),subset:"mesh".into()}})}}],rules:vec![Grid3dRule{id:"permission".into(),tile_a_id:"mesh 🧬".into(),tile_b_id:"child".into(),direction:Grid3dDirection::Front,allowed:false}],pinned:vec![Grid3dPinnedCell{x:u32::MAX,y:2,z:3,tile_id:"child".into()}],masked:vec![Grid3dCell{x:4,y:5,z:6},Grid3dCell{x:0,y:0,z:0}]}}
fn project(s:&Grid3dSnapshot)->SqliteDatabase{s.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
fn restore(d:&SqliteDatabase)->Result<Grid3dSnapshot,String>{Grid3dSnapshot::from_sqlite_database(d,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()))}
#[test]fn sqlite_snapshot_wfc_grid3d_exact_ieee_widths_and_media(){let s=fixture();let d=project(&s);let bytes=export_sqlite_database(&d,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let actual=restore(&import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!(project(&actual),d);assert_eq!(actual.seed,u64::MAX);assert_eq!(actual.cell_sizes_x[0].to_bits(),0x8000000000000000);assert_eq!(actual.cell_sizes_x[1].to_bits(),0x7ff0000000000001);assert_eq!(store::ArtifactPack::encode_pack(&actual),store::ArtifactPack::encode_pack(&s));assert_eq!(store::ArtifactDsl::print_dsl(&actual),store::ArtifactDsl::print_dsl(&s));assert_eq!(restore(&project(&Grid3dSnapshot::default())).unwrap(),Grid3dSnapshot::default());}
#[test]fn sqlite_snapshot_wfc_grid3d_independent_relations_edit(){use std::io::Write;use std::process::{Command,Stdio};let bytes=export_sqlite_database(&project(&fixture()),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok'||d.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const r=d.query('SELECT a.authored_id AS a,b.authored_id AS b,direction FROM wfc_grid3d_rule JOIN wfc_grid3d_tile a ON tile_a_id=a.id JOIN wfc_grid3d_tile b ON tile_b_id=b.id').get();if(r.a!=='mesh 🧬'||r.b!=='child'||r.direction!=='FRONT')throw Error('relationship');d.query('UPDATE wfc_grid3d_color SET red=7').run();await Bun.write(Bun.stdout,d.serialize());";let mut c=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();c.stdin.take().unwrap().write_all(&bytes).unwrap();let o=c.wait_with_output().unwrap();assert!(o.status.success(),"{}",String::from_utf8_lossy(&o.stderr));let restored=restore(&import_sqlite_database(&o.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();if let Grid3dTileMedia::Mesh{mesh}=&restored.tiles[0].media{assert_eq!(mesh.color.unwrap().r,7)}else{panic!("wrong media")}}
#[test]fn sqlite_snapshot_wfc_grid3d_invalid_graph_and_bounds(){let d=project(&fixture());for n in 0..5{let mut m=d.clone();match n{0=>m.table_mut("wfc_grid3d_rule").unwrap().rows[0].values[4]=SqliteValue::Integer(999),1=>m.table_mut("wfc_grid3d_position").unwrap().rows[0].values[2]=SqliteValue::Integer(99),2=>m.table_mut("wfc_grid3d_tile").unwrap().rows[0].values[6]=SqliteValue::Text("unknown".into()),3=>m.table_mut("wfc_grid3d_color").unwrap().rows[0].values[1]=SqliteValue::Integer(-1),_=>m.table_mut("wfc_grid3d_cell_size").unwrap().rows[0].values[5]=SqliteValue::Integer(1)};assert!(restore(&m).is_err())}assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());assert!(Grid3dSnapshot::from_sqlite_database(&d,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:1,..SqliteDatabaseLimits::default()})).is_err());}

#[test]fn sqlite_snapshot_wfc_grid3d_actual_owner_native_admission(){let s=fixture();let codec=crate::standards::v1::subsets::any::io::io().native.codec;let provider=codec.snapshot_sqlite.unwrap();let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.wfc.grid3d".into(),standard:"1".into(),subset:"*".into()};for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{let actual=(provider.import)("grid3d",&dialect,project(&s),encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;let expected=match encoding{SnapshotEncoding::Binary=>store::os_io::IoPayload::Binary(store::ArtifactPack::encode_pack(&s)),SnapshotEncoding::Text=>store::os_io::IoPayload::Text(store::ArtifactDsl::print_dsl(&s))};assert_eq!(actual,expected);assert!(s.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_file_bytes:16,..SqliteDatabaseLimits::default()})).is_err());assert!(s.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());}let wrong=store::os_io::ArtifactDialect{artifact_kind:"s.wfc.grid3d".into(),standard:"1".into(),subset:"named".into()};assert!(s.validate_sqlite_snapshot_subset(&wrong,&project(&s),&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err());}
